"""A real Ghidra worker session for acceptance tests: open generated bytes, call RPC methods, always clean up.

The target is written to a scratch directory and only analyzed, never executed.
"""
from pathlib import Path
import hashlib
import json
import os
import queue
import subprocess
import tempfile
import threading
import time

ROOT = Path(__file__).resolve().parent.parent.parent


class GhidraSession:
    def __init__(self, image, filename='fixture.exe', timeout=180, prefix='ig5-ghidra-'):
        self.scratch = Path(tempfile.mkdtemp(prefix=prefix))
        self.target = self.scratch / filename
        self.image, self.timeout, self.counter, self.messages, self.process = bytes(image), timeout, 0, queue.Queue(), None
        self.target.write_bytes(self.image)

    def __enter__(self):
        runtime_root = ROOT / 'runtimes' / 'ghidra'
        runtime = json.loads((runtime_root / 'runtime.json').read_text(encoding='utf-8-sig'))
        env = os.environ.copy()
        env.update(IG5_GHIDRA_HOME=str(runtime_root / runtime['ghidraHome']), IG5_JAVA_HOME=str(runtime_root / runtime['javaHome']),
                   IG5_GHIDRA_PROJECT_ROOT=str(self.scratch / 'projects'))
        self.log = (self.scratch / 'stderr.log').open('w', encoding='utf-8')
        self.process = subprocess.Popen([str(runtime_root / runtime['pythonExe']), '-I', '-B', str(ROOT / 'adapters/ghidra/worker.py')], env=env,
                                        stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=self.log, encoding='utf-8',
                                        creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
        threading.Thread(target=lambda: ([self.messages.put(line) for line in self.process.stdout], self.messages.put(None)), daemon=True).start()
        self._receive(lambda m: m.get('ig5') == 'ready')
        self.opened = self.rpc('open', {'path': str(self.target), 'auto': True, 'fresh': True})
        return self

    def _receive(self, predicate):
        deadline = time.monotonic() + self.timeout
        while time.monotonic() < deadline:
            line = self.messages.get(timeout=max(0.1, deadline - time.monotonic()))
            if line is None:
                raise AssertionError('Ghidra worker exited; see ' + str(self.scratch / 'stderr.log'))
            try:
                message = json.loads(line)
            except json.JSONDecodeError:
                continue
            if predicate(message):
                if message.get('error'):
                    raise AssertionError(message['error'])
                return message
        raise AssertionError('Ghidra RPC timeout')

    def rpc(self, method, params=None):
        self.counter += 1
        mark = self.counter
        self.process.stdin.write(json.dumps({'id': mark, 'method': method, 'params': params or {}}) + '\n')
        self.process.stdin.flush()
        return self._receive(lambda m: m.get('id') == mark and ('result' in m or 'error' in m))['result']

    def source_unchanged(self):
        return hashlib.sha256(self.target.read_bytes()).digest() == hashlib.sha256(self.image).digest()

    def __exit__(self, *exc):
        try:
            if self.process and self.process.poll() is None:
                try:
                    self.rpc('close')
                except Exception:
                    pass
        finally:
            if self.process:
                self.process.stdin.close()
                try:
                    self.process.wait(timeout=10)
                except subprocess.TimeoutExpired:
                    self.process.kill()
                    self.process.wait(timeout=10)
            self.log.close()
        return False
